// La respuesta del Ministerio es JSON metido en texto varias veces:
// "..." -> { Id, Tipo, Contenido: "...", Fecha } -> Contenido -> { Productos: [...] }
let value = $input.first().json.data;
for (let i = 0; i < 4 && typeof value === 'string'; i++) value = JSON.parse(value);
const fecha = String(value.Fecha || '').slice(0, 10);
const contenido = typeof value.Contenido === 'string' ? JSON.parse(value.Contenido) : value.Contenido;
const productos = contenido?.Productos;
if (!fecha || !Array.isArray(productos) || productos.length === 0) {
  throw new Error('El fichero del registro no tiene el formato esperado: puede que el Ministerio haya cambiado su web.');
}

const text = (v) => (v == null ? '' : String(v).trim());
const num = (v) => (typeof v === 'number' && v > 0 ? v : null);

// Solo los campos que usa FitoPrice; sin los textos largos de condicionamientos
const trimmed = productos.map((p) => {
  const d = p.DATOSPRODUCTO || {};
  const nombres = [d.Nombre, ...(p.OTROSNOMBRES || []).map((o) => o.Nombre), ...(p.OTRASDENOMINACIONES || []).map((o) => o.Nombre_Origen)]
    .map(text).filter(Boolean);

  const seen = new Set();
  const usos = [];
  for (const u of p.USOS || []) {
    const uso = {
      cultivo: text(u.Cultivo),
      agente: text(u.Agente),
      dosis_min: num(u.Dosis_Min),
      dosis_max: num(u.Dosis_Max),
      unidad: text(u['Unidad Medida dosis']),
      plazo_seguridad: text(u['Plazo Seguridad']),
      aplicaciones: text(u.Aplicaciones),
      intervalo: text(u.IntervaloAplicaciones),
      sistema: text(u.SistemaCultivo),
      usuario: text(u.TipoUsuario),
    };
    const key = JSON.stringify(uso);
    if (!seen.has(key)) { seen.add(key); usos.push(uso); }
  }

  return {
    num_registro: text(d.Num_Registro),
    nombre: text(d.Nombre),
    nombres: [...new Set(nombres)],
    titular: text(d.Titular),
    formulado: text(d.Formulado),
    estado: text(d.Estado),
    fecha_caducidad: text(d.Fecha_Caducidad),
    composicion: (p.COMPOSICION || []).map((c) => ({
      sustancia: text(c['Nombre Sustancia']),
      concentracion: typeof c.Concentracion === 'number' ? c.Concentracion : null,
      unidad: text(c.DescripcionNota),
    })),
    usos,
  };
}).filter((p) => p.num_registro && p.nombre);

// Lotes de 100 productos: la API acepta hasta 25 MB por petición
const SIZE = 100;
const batches = [];
for (let i = 0; i < trimmed.length; i += SIZE) {
  batches.push({ json: { fecha, last: i + SIZE >= trimmed.length, productos: trimmed.slice(i, i + SIZE) } });
}
return batches;
